"""Tiny back-office prototype for independent restaurants:
weekly inventory counts -> usage -> supplier order suggestions."""
import json, sys
from statistics import mean

def load(path="counts.json"):
    try:
        with open(path) as f:
            return json.load(f)
    except FileNotFoundError:
        return {"items": {}}

def record_count(data, item, week, qty, par, unit_cost):
    data["items"].setdefault(item, {"par": par, "unit_cost": unit_cost, "counts": []})
    data["items"][item]["counts"].append({"week": week, "qty": qty})
    return data

def weekly_usage(counts):
    return [max(0, a["qty"] - b["qty"]) for a, b in zip(counts, counts[1:])]

def suggest_orders(data):
    rows = []
    for item, info in data["items"].items():
        counts = info["counts"]
        if not counts:
            continue
        usage = weekly_usage(counts) or [0]
        avg = mean(usage)
        on_hand = counts[-1]["qty"]
        need = max(0, round(avg * 1.2 + info["par"] - on_hand))  # 20% buffer + par level
        if need:
            rows.append((item, on_hand, round(avg, 1), need, round(need * info["unit_cost"], 2)))
    return rows

if __name__ == "__main__":
    data = load()
    if len(sys.argv) > 1 and sys.argv[1] == "order":
        print(f"{'item':20} {'on_hand':>8} {'avg/wk':>7} {'order':>6} {'est $':>8}")
        for r in suggest_orders(data):
            print(f"{r[0]:20} {r[1]:>8} {r[2]:>7} {r[3]:>6} {r[4]:>8}")
    else:
        print("usage: python inventory.py order   (reads counts.json)")
