# Unit normalization for dry goods. Base unit: lb (weight) or each (count).
# SAMPLE DATA ONLY until parents send real counts (deadline: week 22).
TO_LB = {"lb": 1.0, "oz": 1/16, "kg": 2.20462, "bag25": 25.0, "bag50": 50.0}
CASE_LB = {"case": None}  # case weight varies by supplier; must be entered per item

def to_lb(qty, unit, case_lb=None):
    if unit == "case":
        if case_lb is None:
            raise ValueError("case weight unknown; enter it per item")
        return qty * case_lb
    if unit not in TO_LB:
        raise ValueError(f"unknown unit: {unit}")
    return qty * TO_LB[unit]

def suggest_order(item, on_hand, par, usage_per_week, unit="lb", pack_size=None):
    """Order = par - on_hand (stock on hand subtracted first), in purchase units."""
    need = max(0.0, par - on_hand)
    if pack_size:
        import math
        return math.ceil(need / pack_size)  # purchase units (bags/cases)
    return round(need, 2)

if __name__ == "__main__":
    # sample data, not real restaurant counts
    print("rice (sample):", suggest_order("rice", on_hand=12, par=40, usage_per_week=10, unit="lb", pack_size=25))
    print("oil case (sample):", to_lb(2, "case", case_lb=35.0))
    assert suggest_order("flour", on_hand=50, par=40, usage_per_week=5) == 0.0
    assert to_lb(1, "bag50") == 50.0
    try:
        to_lb(1, "case")
    except ValueError as e:
        print("expected:", e)
    print("tests ok")

